using Microsoft.EntityFrameworkCore;using TechStore.App.Data;using TechStore.App.Enums;using TechStore.App.Models;
namespace TechStore.App.Services; public class AccountService(TechStoreDbContext db){public async Task<CurrentAccountMovement> RegisterPaymentAsync(int customerId,decimal amount,string description){if(amount<=0)throw new InvalidOperationException("El importe debe ser mayor que cero.");await using var tx=await db.Database.BeginTransactionAsync();var c=await db.Customers.SingleAsync(x=>x.Id==customerId);if(amount>c.CurrentAccountBalance)throw new InvalidOperationException("El pago no puede superar el saldo.");c.CurrentAccountBalance-=amount;var movement=new CurrentAccountMovement{Customer=c,Date=DateTime.Now,MovementType=CurrentAccountMovementType.Pago,Description=string.IsNullOrWhiteSpace(description)?"Pago de cuenta corriente":description,Credit=amount,Balance=c.CurrentAccountBalance};db.Add(movement);await db.SaveChangesAsync();await tx.CommitAsync();return movement;}}
